import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const SRC = 'assets/documents/blank.docx';
const OUT = 'src/generated/blank-docx.ts';

const bytes = readFileSync(SRC);
mkdirSync('src/generated', { recursive: true });
writeFileSync(
  OUT,
  '// AUTO-GENERATED by scripts/generate-blank-docx.mjs - do not edit.\n' +
    'export const BLANK_DOCX_BASE64 =\n  ' +
    JSON.stringify(bytes.toString('base64')) +
    ';\n',
);
console.log(`Wrote ${OUT} (${(bytes.length / 1024).toFixed(1)} KB base64)`);